#!/usr/bin/env bash
# PreToolUse (Write|Edit): contracts/openapi.json is generated by `just contracts`,
# so a hand edit would drift from the server it describes.
set -euo pipefail

file=$(jq -r '.tool_input.file_path // empty')

case "$file" in
  */contracts/openapi.json | contracts/openapi.json)
    jq -n '{hookSpecificOutput: {
      hookEventName: "PreToolUse",
      permissionDecision: "deny",
      permissionDecisionReason: "contracts/openapi.json is generated. Change the API code, then run `just contracts` to regenerate it."
    }}'
    ;;
esac
